import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent } from "react";
import { io, type Socket } from "socket.io-client";
import { Activity, ArrowLeft, ArrowRight, AudioLines, BarChart3, BookOpen, Check, ChevronDown, ChevronRight, Clock3, Coins, Crosshair, Factory, FlaskConical, Globe2, Handshake, Hammer, LockKeyhole, LogOut, Menu, Plus, Radio, RefreshCw, Send, Settings, Shield, Ship, Swords, Target, Users, Wheat, X, Zap, Trophy, Eye, EyeOff, BadgeCheck, Pickaxe, ScrollText } from "lucide-react";
import type { BuildingType, CountryInfo, GameState, GameUnit, Profile, RoomMode, RoomPlayer, RoomSettings, RoomSummary } from "@worldfront/shared";
import WorldMap from "./map/WorldMap";

const API = (import.meta.env.VITE_API_URL || (import.meta.env.DEV ? "http://localhost:3001" : "")).replace(/\/+$/, "");
const SOCKET_URL = (import.meta.env.VITE_SOCKET_URL || API).replace(/\/+$/, "");
type Page = "home" | "single" | "online" | "create" | "profile" | "ranking" | "settings" | "lobby" | "game";
type MapMode = "political" | "economic" | "military" | "diplomacy";
type Panel = "overview" | "economy" | "military" | "diplomacy" | "technology" | "espionage";
type Rules = { buildings: Record<BuildingType,{name:string;cost:{money:number;ore:number};turns:number;effect:string}>; units: Record<GameUnit,{name:string;cost:{money:number;ore:number;oil:number};attack:number;defense:number;speed:number;upkeep:number;tech:string|null}>; technologies: Record<string,{name:string;category:string;cost:number;turns:number;requires:string[];effect:string}> };
type ChatMessage = { id:string;playerId:string;playerName:string;text:string;time:number };
type SecretChanges = { money:number; population:number; military:number; production:number; attack:number; defense:number; technology:number; moral:number; resources:{oil:number;ore:number;food:number;energy:number}; infiniteResources:boolean;infiniteTroops:boolean;instantBuild:boolean;instantResearch:boolean;noCooldown:boolean;godMode:boolean };
const modeNames: Record<RoomMode,string> = {domination:"Dominação",economic:"Econômica",military:"Militar",score:"Pontuação",time:"Tempo"};
const resourceNames: Record<string,string> = {money:"Créditos",oil:"Petróleo",ore:"Minério",food:"Alimentos",energy:"Energia"};
const unitKeys: GameUnit[] = ["infantry","tanks","artillery","special","fighters","bombers","drones","ships","submarines","carriers","missiles"];
const buildingKeys: BuildingType[] = ["farm","mine","power_plant","factory","port","railway","base","research_center"];
const unitIcons: Record<GameUnit, typeof Shield> = {infantry:Shield,tanks:Crosshair,artillery:Target,special:BadgeCheck,fighters:Zap,bombers:Crosshair,drones:Eye,ships:Ship,submarines:Ship,carriers:Ship,missiles:Target};
const iconByBuilding: Record<BuildingType, typeof Hammer> = {farm:Wheat,mine:Pickaxe,power_plant:Zap,factory:Factory,port:Ship,railway:ArrowRight,base:Shield,research_center:FlaskConical};
const emptySecret = (): SecretChanges => ({money:0,population:0,military:0,production:0,attack:0,defense:0,technology:0,moral:70,resources:{oil:0,ore:0,food:0,energy:0},infiniteResources:false,infiniteTroops:false,instantBuild:false,instantResearch:false,noCooldown:false,godMode:false});

async function jsonRequest<T>(path: string, token?: string, init: RequestInit = {}): Promise<T> {
  let response: Response;
  try { response = await fetch(`${API}${path}`, { ...init, headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(init.body ? { "Content-Type":"application/json" } : {}), ...init.headers } }); }
  catch { throw new Error("O servidor do WorldFront está indisponível. Verifique a conexão e tente novamente."); }
  const payload = await response.json().catch(() => ({})) as T & {error?:string};
  if (!response.ok) throw new Error(payload.error ?? `Falha na comunicação (${response.status}).`);
  return payload;
}

export default function App() {
  const [page,setPage] = useState<Page>("home"); const [panel,setPanel] = useState<Panel>("overview"); const [drawer,setDrawer] = useState(false);
  const [profile,setProfile] = useState<Profile|null>(null); const [token,setToken] = useState(""); const [boot,setBoot] = useState("Conectando ao quartel-general…"); const [online,setOnline] = useState(false);
  const [countries,setCountries] = useState<CountryInfo[]>([]); const [rules,setRules] = useState<Rules|null>(null); const [rooms,setRooms] = useState<RoomSummary[]>([]); const [lobby,setLobby] = useState<RoomSummary|null>(null); const [game,setGame] = useState<GameState|null>(null); const [messages,setMessages] = useState<ChatMessage[]>([]); const [socket,setSocket] = useState<Socket|null>(null);
  const [selected,setSelected] = useState<string|null>(null); const [mapMode,setMapMode] = useState<MapMode>("political"); const [notice,setNotice] = useState(""); const [busy,setBusy] = useState(false); const [chatText,setChatText] = useState(""); const [chatExpanded,setChatExpanded] = useState(false); const [filter,setFilter] = useState(""); const [mobileTab,setMobileTab] = useState<"map"|"info">("map");
  const [roomName,setRoomName] = useState(""); const [maxPlayers,setMaxPlayers] = useState(6); const [roomMode,setRoomMode] = useState<RoomMode>("domination"); const [roomPassword,setRoomPassword] = useState(""); const [roomPrivate,setRoomPrivate] = useState(false); const [fog,setFog] = useState(true); const [diplomacy,setDiplomacy] = useState(true); const [aiCount,setAiCount] = useState(3); const [speed,setSpeed] = useState(1); const [duration,setDuration] = useState(30);
  const [soloCountry,setSoloCountry] = useState("076"); const [difficulty,setDifficulty] = useState<"easy"|"normal"|"hard">("normal"); const [secretOpen,setSecretOpen] = useState(false); const [secret,setSecret] = useState<SecretChanges>(emptySecret); const [sound,setSound] = useState(() => localStorage.getItem("wf-sound") !== "off");
  const socketRef=useRef<Socket|null>(null); const booted=useRef(false); const currentRoomRef=useRef(localStorage.getItem("wf-room")??"");
  const lastEventSound=useRef("");

  const flash = useCallback((message:string) => { setNotice(message); window.setTimeout(()=>setNotice(current=>current===message?"":current),5500); },[]);
  const startSocket = useCallback((session:string,playerId:string) => {
    socketRef.current?.disconnect(); const next=io(SOCKET_URL,{auth:{token:session},transports:["websocket","polling"]}); socketRef.current=next; setSocket(next);
    next.on("connect",()=>setOnline(true)); next.on("disconnect",()=>setOnline(false)); next.on("connect_error",()=>setOnline(false));
    next.on("rooms:updated",(value:RoomSummary[])=>setRooms(value)); next.on("lobby:updated",(value:RoomSummary)=>{if(currentRoomRef.current===value.id)setLobby(value);});
    next.on("game:state",(value:GameState)=>{if(currentRoomRef.current!==value.roomId)return;setGame(value);setLobby(current=>current?.id===value.roomId?{...current,status:value.status==="active"?"in_progress":"finished"}:current);setPage(current=>current==="lobby"?"game":current); if(value.status==="finished")flash(`${value.winnerName??"A partida"} venceu a campanha.`);});
    next.on("chat:history",(value:ChatMessage[])=>setMessages(value)); next.on("chat:message",(message:ChatMessage)=>setMessages(current=>[...current.filter(m=>m.id!==message.id),message].slice(-80)));
    void jsonRequest<{rooms:RoomSummary[]}>("/api/rooms",session).then(data=>setRooms(data.rooms)).catch(()=>{});
    void jsonRequest<{countries:CountryInfo[]}>("/api/countries").then(data=>{setCountries(data.countries);const brazil=data.countries.find(c=>c.code==="BRA");if(brazil)setSoloCountry(brazil.id);}).catch(e=>flash(e.message));
    void jsonRequest<Rules>("/api/rules").then(setRules).catch(e=>flash(e.message));
    void jsonRequest<{ranking:Profile[]}>("/api/ranking").catch(()=>{}); void playerId;
  },[]);

  useEffect(()=>{let alive=true;const initialize=async()=>{try{let session=localStorage.getItem("wf-token")??"";let current:Profile|null=null;if(session){try{current=(await jsonRequest<{profile:Profile}>("/api/profile",session)).profile;}catch{session="";localStorage.removeItem("wf-token");}}
      if(!session){const name=localStorage.getItem("wf-player")??"Comandante";const result=await jsonRequest<{profile:Profile;sessionToken:string}>("/api/players/guest",undefined,{method:"POST",body:JSON.stringify({name})});session=result.sessionToken;current=result.profile;localStorage.setItem("wf-token",session);}
      if(!alive)return;setToken(session);setProfile(current);setBoot("");
      const savedRoom=currentRoomRef.current;if(savedRoom){try{const saved=await jsonRequest<{room:RoomSummary;game:GameState|null;messages:ChatMessage[]}>(`/api/rooms/${savedRoom}`,session);if(!alive)return;setLobby(saved.room);setGame(saved.game);setMessages(saved.messages);setPage(saved.game?"game":"lobby");}catch{currentRoomRef.current="";localStorage.removeItem("wf-room");}}
      startSocket(session,current!.id);
    }catch(error){if(alive)setBoot(error instanceof Error?error.message:"Não foi possível iniciar a sessão.");}};void initialize();return()=>{alive=false;};},[startSocket]);
  useEffect(()=>()=>{socketRef.current?.disconnect();},[]);
  useEffect(()=>{const event=game?.events[0];if(!event)return;if(!lastEventSound.current){lastEventSound.current=event.id;return;}if(lastEventSound.current===event.id)return;lastEventSound.current=event.id;if(!sound)return;const Context=window.AudioContext;if(!Context)return;const context=new Context();const oscillator=context.createOscillator();const gain=context.createGain();oscillator.type="sine";oscillator.frequency.value=event.type==="war"||event.type==="combat"?220:event.type==="conquest"?740:480;gain.gain.setValueAtTime(0.035,context.currentTime);gain.gain.exponentialRampToValueAtTime(0.001,context.currentTime+0.16);oscillator.connect(gain);gain.connect(context.destination);oscillator.start();oscillator.stop(context.currentTime+0.16);oscillator.onended=()=>void context.close();},[game?.events[0]?.id,sound]);
  useEffect(()=>{if(socket&&lobby&&(page==="lobby"||page==="game")){socket.emit("room:watch",{roomId:lobby.id});}},[socket,lobby?.id,page]);
  useEffect(()=>{if(!profile||!token||booted.current)return;booted.current=true;},[profile,token]);
  useEffect(()=>{const onKey=(event:KeyboardEvent)=>{const secretKey=event.key.toLocaleLowerCase()==="ç"||event.code==="Semicolon";if(event.shiftKey&&secretKey&&game&&selected){event.preventDefault();setSecretOpen(value=>!value);}};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey);},[game,selected]);

  const api=useCallback(<T,>(path:string,init:RequestInit={})=>jsonRequest<T>(path,token,init),[token]);
  const navigate=(target:Page)=>{setPage(target);setDrawer(false);setNotice("");if(target==="online")void api<{rooms:RoomSummary[]}>("/api/rooms").then(x=>setRooms(x.rooms)).catch(e=>flash(e.message));if(target==="ranking")void api<{ranking:Profile[]}>("/api/ranking").then(()=>{}).catch(e=>flash(e.message));};
  const updateLobby=(next:RoomSummary)=>{currentRoomRef.current=next.id;localStorage.setItem("wf-room",next.id);setLobby(next);setPage(next.status==="waiting"?"lobby":"game");};
  const joinRoom=async(room:RoomSummary)=>{try{let password:string|undefined;if(room.private){password=window.prompt("Senha da sala privada")??undefined;if(password===undefined)return;}const result=await api<{room:RoomSummary}>(`/api/rooms/${room.id}/join`,{method:"POST",body:JSON.stringify({password})});updateLobby(result.room);}catch(e){flash(e instanceof Error?e.message:"Não foi possível entrar na sala.");}};
  const createRoom=async(event:FormEvent)=>{event.preventDefault();setBusy(true);try{const settings:RoomSettings={maxPlayers,mode:roomMode,private:roomPrivate,password:roomPrivate?roomPassword||undefined:undefined,duration,speed,fogOfWar:fog,diplomacy,aiCount};const result=await api<{room:RoomSummary}>("/api/rooms",{method:"POST",body:JSON.stringify({name:roomName,settings})});updateLobby(result.room);}catch(e){flash(e instanceof Error?e.message:"Falha ao criar sala.");}finally{setBusy(false);}};
  const startSingle=async(event:FormEvent)=>{event.preventDefault();setBusy(true);try{const result=await api<{room:RoomSummary;game:GameState}>("/api/singleplayer",{method:"POST",body:JSON.stringify({countryId:soloCountry,aiCount,difficulty,settings:{mode:roomMode,fogOfWar:fog,diplomacy,speed,duration}})});updateLobby(result.room);setGame(result.game);setSelected(soloCountry);setPage("game");setPanel("overview");}catch(e){flash(e instanceof Error?e.message:"Não foi possível começar a campanha.");}finally{setBusy(false);}};
  const roomCountry=async(countryId:string)=>{if(!lobby)return;try{const result=await api<{room:RoomSummary}>(`/api/rooms/${lobby.id}/country`,{method:"PATCH",body:JSON.stringify({countryId})});setLobby(result.room);}catch(e){flash(e instanceof Error?e.message:"País indisponível.");}};
  const roomReady=async(ready:boolean)=>{if(!lobby)return;try{const result=await api<{room:RoomSummary}>(`/api/rooms/${lobby.id}/ready`,{method:"PATCH",body:JSON.stringify({ready})});setLobby(result.room);}catch(e){flash(e instanceof Error?e.message:"Erro ao atualizar prontidão.");}};
  const startLobby=async()=>{if(!lobby)return;setBusy(true);try{const result=await api<{room:RoomSummary;game:GameState}>(`/api/rooms/${lobby.id}/start`,{method:"POST",body:JSON.stringify({})});setLobby(result.room);setGame(result.game);setSelected(lobby.playerList?.find(p=>p.id===profile?.id)?.countryId??null);setPage("game");setPanel("overview");}catch(e){flash(e instanceof Error?e.message:"Não foi possível iniciar.");}finally{setBusy(false);}};
  const leaveRoom=async()=>{if(!lobby)return;try{await api(`/api/rooms/${lobby.id}/leave`,{method:"DELETE"});}catch(e){flash(e instanceof Error?e.message:"Não foi possível sair da sala.");}socket?.emit("room:unwatch",{roomId:lobby.id});currentRoomRef.current="";localStorage.removeItem("wf-room");setLobby(null);setGame(null);setMessages([]);setPage("online");};
  const forfeitGame=async()=>{if(!lobby)return;try{await api(`/api/rooms/${lobby.id}/forfeit`,{method:"POST"});socket?.emit("room:unwatch",{roomId:lobby.id});currentRoomRef.current="";localStorage.removeItem("wf-room");setLobby(null);setGame(null);setMessages([]);setPage("online");}catch(e){flash(e instanceof Error?e.message:"Não foi possível abandonar a campanha.");}};
  const sendAction=async(action:Record<string,unknown>,silent=false)=>{if(!lobby)return;setBusy(true);try{const result=await api<{game:GameState}>(`/api/rooms/${lobby.id}/actions`,{method:"POST",body:JSON.stringify(action)});setGame(result.game);if(!silent)flash("Ordem validada pelo comando central.");}catch(e){flash(e instanceof Error?e.message:"A ordem falhou.");}finally{setBusy(false);}};
  const setCountryName=async(name:string)=>{if(!profile)return;try{const result=await api<{profile:Profile}>("/api/profile",{method:"PATCH",body:JSON.stringify({name})});setProfile(result.profile);localStorage.setItem("wf-player",result.profile.name);flash("Perfil salvo no servidor.");}catch(e){flash(e instanceof Error?e.message:"Não foi possível salvar.");}};
  const sendMessage=async(event:FormEvent)=>{event.preventDefault();if(!lobby||!chatText.trim())return;try{await api(`/api/rooms/${lobby.id}/chat`,{method:"POST",body:JSON.stringify({text:chatText})});setChatText("");}catch(e){flash(e instanceof Error?e.message:"Falha ao enviar mensagem.");}};
  const applySecret=async()=>{if(!lobby||!selected)return;const changes={money:secret.money||undefined,population:secret.population||undefined,military:secret.military||undefined,production:secret.production||undefined,attack:secret.attack||undefined,defense:secret.defense||undefined,technology:secret.technology||undefined,moral:secret.moral||undefined,resources:{oil:secret.resources.oil||undefined,ore:secret.resources.ore||undefined,food:secret.resources.food||undefined,energy:secret.resources.energy||undefined},infiniteResources:secret.infiniteResources,infiniteTroops:secret.infiniteTroops,instantBuild:secret.instantBuild,instantResearch:secret.instantResearch,noCooldown:secret.noCooldown,godMode:secret.godMode};await sendAction({type:"black_ops",countryId:selected,changes},true);setSecretOpen(false);flash("— Ordem recebida.");};

  const ownNations=useMemo(()=>game?Object.values(game.nations).filter(n=>n.ownerId===profile?.id):[],[game,profile?.id]);
  const primaryNation=ownNations.find(n=>n.countryId===selected)??ownNations[0]??null;
  const selectedCountry=countries.find(c=>c.id===selected)??null; const targetNation=selected?game?.nations[selected]??null:null;
  const activePlayer=game?.players.find(p=>p.id===game.activePlayerId); const selectedOwner=targetNation?.ownerId?game?.players.find(p=>p.id===targetNation.ownerId):null;

  const nav=<><button className={page==="home"?"active":""} onClick={()=>navigate("home")}><Globe2/>Centro de comando</button><button className={page==="single"?"active":""} onClick={()=>navigate("single")}><Swords/>Campanha solo</button><button className={page==="online"||page==="create"?"active":""} onClick={()=>navigate("online")}><Radio/>Jogo online</button><div className="nav-label">COMUNIDADE</div><button onClick={()=>navigate("profile")}><Users/>Perfil</button><button onClick={()=>navigate("ranking")}><Trophy/>Ranking</button><div className="nav-label">SISTEMA</div><button onClick={()=>navigate("settings")}><Settings/>Configurações</button></>;

  if(boot)return <div className="boot-screen"><div className="brand-mark"><Globe2/></div><span>{boot}</span><button className="secondary-button" onClick={()=>window.location.reload()}><RefreshCw size={15}/> RECARREGAR</button></div>;

  return <div className="shell"><aside className="sidebar"><button className="brand" onClick={()=>navigate("home")}><span className="brand-mark"><Globe2 size={20}/></span><span>WORLD<span className="brand-light">FRONT</span><small>STRATEGIC COMMAND</small></span></button><div className="nav-section">COMANDO</div><nav>{nav}</nav><div className="sidebar-bottom"><div className="server-card"><span className={`status-dot ${online?"online":"offline"}`}/><span>Servidor {online?"conectado":"reconectando"}</span><span className="server-region">LIVE</span></div><button className="user-card" onClick={()=>navigate("profile")}><span className="avatar">{profile?.avatar??"C"}</span><span className="user-name">{profile?.name??"Comandante"}<small>Força de comando</small></span><ChevronDown size={15}/></button></div></aside>
    <main className="main"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setDrawer(true)} aria-label="Abrir menu"><Menu/></button><div className="breadcrumb">WORLD FRONT <span>/</span> {page.toUpperCase()}</div><div className="top-actions">{page==="game"&&game&&<span className="turn-chip"><Clock3 size={14}/> CICLO {game.turn} <i>·</i> {modeNames[game.mode]}</span>}<span className="build-label"><span className={online?"green-dot":""}/> {online?"AO VIVO":"OFFLINE"}</span><button className="icon-button" onClick={()=>{const next=!sound;setSound(next);localStorage.setItem("wf-sound",next?"on":"off");}} title="Preferência de áudio" aria-label="Ativar ou desativar sons"><AudioLines size={17} className={sound?"":"muted"}/></button><button className="icon-button" onClick={()=>navigate("settings")} aria-label="Configurações"><Settings size={17}/></button></div></header>
      <section className="content">
        {notice&&<div className="notice"><Activity size={16}/>{notice}<button onClick={()=>setNotice("")} aria-label="Fechar"><X size={16}/></button></div>}
        {page==="home"&&<HomePage onSingle={()=>navigate("single")} onOnline={()=>navigate("online")} onCreate={()=>navigate("create")} online={online} playerName={profile?.name??"Comandante"}/>}
        {page==="single"&&<div className="subpage"><button className="back-link" onClick={()=>navigate("home")}><ArrowLeft size={15}/> CENTRO DE COMANDO</button><div className="eyebrow"><span className="eyebrow-line"/> CAMPANHA SOLO · JOGO SALVO NO SERVIDOR</div><h1 className="subpage-title">Defina sua <em>estratégia.</em></h1><p className="subpage-lede">Escolha uma nação e desafie uma IA que produz, pesquisa e expande seu poder a cada ciclo.</p><form className="form-card wide-form" onSubmit={startSingle}><label>País de comando<select value={soloCountry} onChange={e=>setSoloCountry(e.target.value)}>{countries.slice().sort((a,b)=>b.population-a.population).map(c=><option key={c.id} value={c.id}>{c.name} · {c.population.toFixed(0)}M · {c.continent}</option>)}</select></label><div className="form-row"><label>Dificuldade<select value={difficulty} onChange={e=>setDifficulty(e.target.value as typeof difficulty)}><option value="easy">Fácil · IA cautelosa</option><option value="normal">Normal · IA estratégica</option><option value="hard">Difícil · IA agressiva</option></select></label><label>Países de IA<select value={aiCount} onChange={e=>setAiCount(Number(e.target.value))}>{[1,2,3,4,5,6,7,8].map(n=><option key={n} value={n}>{n} nações adversárias</option>)}</select></label></div><div className="form-row"><label>Condição de vitória<select value={roomMode} onChange={e=>setRoomMode(e.target.value as RoomMode)}>{Object.entries(modeNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Velocidade dos ciclos<select value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value={1}>Estratégica · 90 s por jogada</option><option value={2}>Acelerada · 45 s por jogada</option><option value={4}>Relâmpago · 22 s por jogada</option></select></label></div><label>Duração máxima<select value={duration} onChange={e=>setDuration(Number(e.target.value))}>{[10,20,30,60,90].map(n=><option key={n} value={n}>{n} ciclos</option>)}</select></label><Toggle label="Fog of War" detail="Inteligência militar é revelada apenas em territórios próximos." checked={fog} setChecked={setFog}/><Toggle label="Diplomacia ativa" detail="Tratados, alianças e comércio entre comandantes." checked={diplomacy} setChecked={setDiplomacy}/><button className="primary-button" type="submit" disabled={busy||!countries.length}>{busy?"PREPARANDO TEATRO…":"INICIAR CAMPANHA"}<ArrowRight size={17}/></button></form></div>}
        {page==="online"&&<div className="subpage"><div className="eyebrow"><span className="eyebrow-line"/> MULTIPLAYER · SOCKET.IO</div><h1 className="subpage-title">Frentes <em>ativas.</em></h1><p className="subpage-lede">Salas persistentes no servidor. Estado da partida sincronizado em tempo real.</p><div className="room-toolbar"><span>{rooms.length} SALAS PÚBLICAS <button className="refresh-inline" onClick={()=>void api<{rooms:RoomSummary[]}>("/api/rooms").then(x=>setRooms(x.rooms)).catch(e=>flash(e.message))}><RefreshCw size={13}/> ATUALIZAR</button></span><button className="primary-button" onClick={()=>navigate("create")}><Plus size={16}/> CRIAR SALA</button></div><div className="room-list">{rooms.length?rooms.map(room=><div className="room-row" key={room.id}><span className="room-code">{room.id}</span><span className="room-name">{room.name}<small>{modeNames[room.mode]} · {room.settings.fogOfWar?"Fog of War":"Mapa revelado"}</small></span><span className="room-host">HOST <b>{room.hostName}</b></span><span className="room-count"><Users size={15}/>{room.players}/{room.maxPlayers}</span><button className="join-button" disabled={room.status!=="waiting"||busy} onClick={()=>void joinRoom(room)}>{room.private?<LockKeyhole size={13}/>:"ENTRAR"}<ChevronRight size={13}/></button></div>):<div className="empty-state"><Radio size={25}/><b>Nenhuma frente aberta.</b><span>Crie uma sala ou atualize a lista. Salas e partidas são compartilhadas pelo servidor.</span></div>}</div><div className="persistent-note"><LockKeyhole size={14}/> Partidas e perfis são salvos localmente no servidor neste ambiente.</div></div>}
        {page==="create"&&<div className="subpage"><button className="back-link" onClick={()=>navigate("online")}><ArrowLeft size={15}/> LISTA DE SALAS</button><div className="eyebrow"><span className="eyebrow-line"/> CRIAR MULTIPLAYER</div><h1 className="subpage-title">Abra uma <em>frente.</em></h1><form className="form-card wide-form" onSubmit={createRoom}><label>Nome da sala<input value={roomName} onChange={e=>setRoomName(e.target.value)} minLength={3} maxLength={40} placeholder="Ex.: Nova Ordem Mundial" required/></label><div className="form-row"><label>Limite de jogadores<select value={maxPlayers} onChange={e=>setMaxPlayers(Number(e.target.value))}>{[2,3,4,6,8,10,12].map(n=><option key={n} value={n}>{n} jogadores</option>)}</select></label><label>Nações controladas por IA<select value={aiCount} onChange={e=>setAiCount(Number(e.target.value))}>{Array.from({length:Math.max(1,maxPlayers-1)},(_,i)=>i).map(n=><option key={n} value={n}>{n} nações</option>)}</select></label></div><div className="form-row"><label>Vitória<select value={roomMode} onChange={e=>setRoomMode(e.target.value as RoomMode)}>{Object.entries(modeNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Velocidade<select value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value={1}>Estratégica</option><option value={2}>Acelerada</option><option value={4}>Relâmpago</option></select></label></div><label>Duração máxima<select value={duration} onChange={e=>setDuration(Number(e.target.value))}>{[10,20,30,60,90].map(n=><option key={n} value={n}>{n} ciclos</option>)}</select></label><Toggle label="Fog of War" detail="Oculta informações militares fora do alcance de inteligência." checked={fog} setChecked={setFog}/><Toggle label="Diplomacia" detail="Permite propor tratados e negociar recursos." checked={diplomacy} setChecked={setDiplomacy}/><Toggle label="Sala privada" detail="Exige senha para outros comandantes entrarem." checked={roomPrivate} setChecked={setRoomPrivate}/>{roomPrivate&&<label>Senha<input value={roomPassword} onChange={e=>setRoomPassword(e.target.value)} minLength={4} maxLength={64} type="password" placeholder="Mínimo de 4 caracteres" required/></label>}<button className="primary-button" type="submit" disabled={busy}>{busy?"CRIANDO…":"CRIAR SALA E ABRIR LOBBY"}<ArrowRight size={17}/></button></form></div>}
        {page==="lobby"&&lobby&&profile&&<Lobby room={lobby} profile={profile} countries={countries} busy={busy} onCountry={roomCountry} onReady={roomReady} onStart={startLobby} onLeave={leaveRoom} onJoin={async()=>{const res=await api<{messages:ChatMessage[]}>(`/api/rooms/${lobby.id}`);setMessages(res.messages);}}/>}
        {page==="game"&&game&&lobby&&profile&&<GameScreen game={game} room={lobby} profile={profile} countries={countries} rules={rules} selected={selected} setSelected={(id)=>{setSelected(id);setMobileTab("info");}} mobileTab={mobileTab} setMobileTab={setMobileTab} mode={mapMode} setMode={setMapMode} panel={panel} setPanel={setPanel} onAction={sendAction} onLeave={forfeitGame} onChat={sendMessage} chatText={chatText} setChatText={setChatText} messages={messages} chatExpanded={chatExpanded} setChatExpanded={setChatExpanded} busy={busy} onHome={()=>navigate("home")}/>}
        {page==="profile"&&profile&&<ProfilePage profile={profile} onSave={setCountryName}/>}
        {page==="ranking"&&<RankingPage api={api} flash={flash}/>}
        {page==="settings"&&<SettingsPage profile={profile} sound={sound} setSound={setSound} online={online} onSave={setCountryName}/>}
      </section>
    </main>
    {drawer&&<div className="drawer-backdrop" onClick={()=>setDrawer(false)}><aside className="drawer" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={()=>setDrawer(false)}><X/></button><div className="nav-section">COMANDO</div><nav>{nav}</nav></aside></div>}
    {secretOpen&&game&&lobby&&selected&&<div className="secret-overlay"><section className="secret-panel"><header><span>▣</span><div><b>PAINEL CONFIDENCIAL</b><small>CANAL LOCAL · CHAVE {selected}</small></div><button onClick={()=>setSecretOpen(false)} aria-label="Fechar"><X/></button></header><div className="secret-body"><div className="secret-grid">{(["money","population","military","production","attack","defense","technology","moral"] as const).map(key=><label key={key}>{({money:"CRÉDITOS",population:"POPULAÇÃO (M)",military:"TROPAS ADICIONAIS",production:"PRODUÇÃO (%)",attack:"ATAQUE (%)",defense:"DEFESA (%)",technology:"TECNOLOGIA",moral:"MORAL"})[key]}<input type="number" min="0" max={key==="population"?10000:1000000} value={secret[key]} onChange={e=>setSecret(v=>({...v,[key]:Number(e.target.value)}))}/></label>)}</div><h4>RESERVAS E PROTOCOLOS</h4><div className="secret-grid resource-edit">{(["oil","ore","food","energy"] as const).map(key=><label key={key}>{resourceNames[key].toUpperCase()}<input type="number" min="0" value={secret.resources[key]} onChange={e=>setSecret(v=>({...v,resources:{...v.resources,[key]:Number(e.target.value)}}))}/></label>)}</div><div className="secret-flags">{(["infiniteResources","infiniteTroops","instantBuild","instantResearch","noCooldown","godMode"] as const).map((key,i)=><label key={key}><input type="checkbox" checked={secret[key]} onChange={e=>setSecret(v=>({...v,[key]:e.target.checked}))}/><span>{["Recursos infinitos","Tropas infinitas","Construção instantânea","Pesquisa instantânea","Sem intervalo de turno","Modo Deus"][i]}</span></label>)}</div><button className="secret-apply" onClick={()=>void applySecret()}>APLICAR PROTOCOLO <ArrowRight size={15}/></button></div></section></div>}
  </div>;
}

function Toggle({label,detail,checked,setChecked}:{label:string;detail:string;checked:boolean;setChecked:(value:boolean)=>void}){return <label className="toggle-row"><span><b>{label}</b><small>{detail}</small></span><button className={`switch ${checked?"active":""}`} type="button" onClick={()=>setChecked(!checked)} role="switch" aria-checked={checked}>{checked?<Check size={13}/>:<X size={13}/>}</button></label>}

function HomePage({onSingle,onOnline,onCreate,online,playerName}:{onSingle:()=>void;onOnline:()=>void;onCreate:()=>void;online:boolean;playerName:string}){return <><div className="hero"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-line"/> ESTRATÉGIA GEOPOLÍTICA · COMANDO ATIVO</div><h1>O mundo está<br/>em <em>suas mãos.</em></h1><p>Construa alianças, administre recursos e escreva uma nova ordem mundial. Cada decisão muda o equilíbrio de poder.</p><div className="hero-actions"><button className="primary-button" onClick={onSingle}>COMEÇAR CAMPANHA <ArrowRight size={17}/></button><button className="secondary-button" onClick={onOnline}><Users size={17}/> JOGO ONLINE</button></div><div className="hero-footnote"><span className={`pulse ${online?"":"offline-pulse"}`}/> SERVIDOR {online?"OPERACIONAL":"OFFLINE"} · COMANDANTE {playerName.toUpperCase()}</div></div><div className="globe-stage"><WorldPreview/><div className="globe-caption"><span>GLOBAL THEATER</span><b>WORLD MAP / 01</b></div></div></div><div className="section-heading"><div><div className="eyebrow"><span className="eyebrow-line"/> CENTRO DE OPERAÇÕES</div><h2>Escolha seu próximo movimento</h2></div><span className="section-meta">TEATROS ABERTOS <b>02</b></span></div><div className="mode-grid"><button className="mode-card" onClick={onSingle}><span className="mode-index">01 / CAMPANHA</span><span className="mode-icon"><Shield/></span><span className="mode-title">Single player</span><span className="mode-description">Desafie nações de IA em uma campanha persistente.</span><span className="mode-link">ASSUMIR COMANDO <ArrowRight size={14}/></span></button><button className="mode-card" onClick={onOnline}><span className="mode-index">02 / ONLINE</span><span className="mode-icon"><Radio/></span><span className="mode-title">Multiplayer</span><span className="mode-description">Entre em uma frente ativa e compartilhe o mesmo estado de jogo.</span><span className="mode-link">VER SALAS ATIVAS <ArrowRight size={14}/></span><span className="mode-corner"><Users size={15}/> TEMPO REAL</span></button><div className="intel-card"><div className="intel-top"><span className="intel-icon"><BookOpen size={16}/></span><span className="intel-tag">COMANDO · DADOS REAIS</span><ArrowRight size={15}/></div><h3>Um mapa. Cento e setenta nações.</h3><p>Fronteiras cartográficas reais, economia autoritativa e disputas calculadas no servidor.</p><div className="progress-meta"><span>OPERAÇÕES ATIVAS</span><b>ONLINE <i>·</i> PRONTO</b></div><div className="progress-track"><span/></div></div></div><footer className="footer"><span>WORLD FRONT <i>© 2026</i></span><span>REAL-TIME COMMAND <i>·</i> LOCAL SERVER</span><button onClick={onCreate}>CRIAR SALA <span className="pulse"/></button></footer></>}
function WorldPreview(){return <div className="globe"><div className="globe-grid"/><div className="globe-shade"/><div className="globe-label label-north">NORTH ATLANTIC <i/></div><div className="globe-label label-south"><i/> SOUTH AMERICA</div><span className="globe-marker marker-one"/><span className="globe-marker marker-two"/><span className="globe-marker marker-three"/><div className="coord coord-one">51°30′N<br/><span>LONDON SECTOR</span></div><div className="coord coord-two">23°33′S<br/><span>SOUTH ATLANTIC</span></div></div>}

function Lobby({room,profile,countries,busy,onCountry,onReady,onStart,onLeave}:{room:RoomSummary;profile:Profile;countries:CountryInfo[];busy:boolean;onCountry:(id:string)=>void;onReady:(value:boolean)=>void;onStart:()=>void;onLeave:()=>void;onJoin:()=>void}){
 const players=room.playerList??[];const self=players.find(p=>p.id===profile.id);const isHost=room.hostId===profile.id;const chosen=new Set(players.map(p=>p.countryId).filter(Boolean));
 return <div className="subpage lobby-page"><div className="lobby-heading"><div><button className="back-link" onClick={onLeave}><ArrowLeft size={15}/> SALIR DA SALA</button><div className="eyebrow"><span className="eyebrow-line"/> LOBBY MULTIPLAYER · {room.id}</div><h1 className="subpage-title">{room.name}</h1></div><span className="lobby-status"><span className="pulse"/> AGUARDANDO JOGADORES</span></div><div className="lobby-grid"><section className="lobby-panel"><div className="panel-heading"><span>COMANDANTES</span><b>{players.length} / {room.maxPlayers}</b></div>{players.map(player=><LobbyPlayer key={player.id} player={player} countries={countries} host={player.id===room.hostId} self={player.id===profile.id}/>)}<div className="lobby-settings"><div><span>MODO</span><b>{modeNames[room.mode]}</b></div><div><span>IA</span><b>{room.settings.aiCount} nações</b></div><div><span>FOW</span><b>{room.settings.fogOfWar?"ATIVO":"DESLIGADO"}</b></div><div><span>VELOCIDADE</span><b>{room.settings.speed}×</b></div></div></section><section className="lobby-panel lobby-control"><div className="panel-heading"><span>SELEÇÃO DE NAÇÃO</span><Globe2 size={16}/></div><p>Escolha uma nação livre no mapa. A escolha é validada e compartilhada pelo servidor.</p><label className="select-country">Sua nação<select value={self?.countryId??""} onChange={e=>onCountry(e.target.value)}><option value="">Selecione um país…</option>{countries.slice().sort((a,b)=>b.population-a.population).map(c=><option key={c.id} value={c.id} disabled={chosen.has(c.id)&&self?.countryId!==c.id}>{c.name} · {c.population.toFixed(0)}M</option>)}</select></label><button className={self?.ready?"ready-button":"secondary-button"} disabled={busy||!self?.countryId} onClick={()=>onReady(!self?.ready)}>{self?.ready?<><Check size={16}/> PRONTO · CANCELAR</>:<><BadgeCheck size={16}/> CONFIRMAR PRONTIDÃO</>}</button>{isHost?<button className="primary-button lobby-start" disabled={busy||players.length<1||!players.every(p=>p.countryId&&p.ready)} onClick={onStart}>{busy?"INICIANDO…":"INICIAR PARTIDA"}<ArrowRight size={16}/></button>:<div className="waiting-host"><Clock3 size={14}/> O anfitrião inicia quando todos estiverem prontos.</div>}</section></div></div>;
}
function LobbyPlayer({player,countries,host,self}:{player:RoomPlayer;countries:CountryInfo[];host:boolean;self:boolean}){const country=countries.find(c=>c.id===player.countryId);return <div className={`lobby-player ${self?"self":""}`}><span className="avatar">{player.name[0]?.toUpperCase()}</span><span className="lobby-player-name">{player.name}{self&&<small>VOCÊ</small>}</span><span className="lobby-country">{country?.name??"Escolhendo país"}</span>{host&&<span className="host-tag">HOST</span>}<span className={`ready-state ${player.ready?"is-ready":""}`}>{player.ready?<><Check size={12}/> PRONTO</>:"AGUARDANDO"}</span><span className={`connection-dot ${player.connected?"connected":""}`} title={player.connected?"Conectado":"Reconectando"}/></div>}

function GameScreen({game,room,profile,countries,rules,selected,setSelected,mode,setMode,panel,setPanel,onAction,onLeave,onChat,chatText,setChatText,messages,chatExpanded,setChatExpanded,busy,onHome,mobileTab,setMobileTab}:{game:GameState;room:RoomSummary;profile:Profile;countries:CountryInfo[];rules:Rules|null;selected:string|null;setSelected:(id:string)=>void;mode:MapMode;setMode:(m:MapMode)=>void;panel:Panel;setPanel:(p:Panel)=>void;onAction:(a:Record<string,unknown>,silent?:boolean)=>Promise<void>;onLeave:()=>void;onChat:(e:FormEvent)=>void;chatText:string;setChatText:(v:string)=>void;messages:ChatMessage[];chatExpanded:boolean;setChatExpanded:(v:boolean)=>void;busy:boolean;onHome:()=>void;mobileTab:"map"|"info";setMobileTab:(v:"map"|"info")=>void}){
 const own=Object.values(game.nations).filter(n=>n.ownerId===profile.id);const active=game.activePlayerId===profile.id;const selectedNation=game.nations[selected??""];const ownSelected=selectedNation?.ownerId===profile.id;const selectedInfo=countries.find(c=>c.id===selected);const selectedPlayer=game.players.find(p=>p.id===selectedNation?.ownerId);const [tick,setTick]=useState(Date.now());const [amount,setAmount]=useState(1);const [targetId,setTargetId]=useState("");const [tradeGive,setTradeGive]=useState("money");const [tradeReceive,setTradeReceive]=useState("food");const [tradeAmount,setTradeAmount]=useState(25);
 useEffect(()=>{const interval=window.setInterval(()=>setTick(Date.now()),1000);return()=>window.clearInterval(interval);},[]);
 const remaining=Math.max(0,Math.ceil((game.turnDeadline-tick)/1000));
 const relation=(a:string,b:string)=>game.relations.find(r=>r.countryId===a&&r.targetId===b)?.status??"neutral";
 const targetCountry=selectedInfo;const adjacent=selectedInfo?countries.filter(c=>selectedInfo.neighbors.includes(c.id)) :[];
 const issue=(action:Record<string,unknown>)=>void onAction(action);
 const myNation=own.find(n=>n.countryId===selected)||own[0];
 const panelItems:[Panel,string,typeof Globe2][]=[["overview","Visão geral",Globe2],["economy","Economia",Coins],["military","Militar",Swords],["diplomacy","Diplomacia",Handshake],["technology","Tecnologia",FlaskConical],["espionage","Inteligência",Eye]];
 return <div className={`game-layout ${mobileTab==="info"?"mobile-info":""}`}><aside className="game-rail"><div className="game-country"><div className="eyebrow">SUA NAÇÃO</div><b>{countries.find(c=>c.id===myNation?.countryId)?.name??"Sem território"}</b><small>{profile.name.toUpperCase()} · {game.turn>1?`CICLO ${game.turn}`:"PRIMEIRO CICLO"}</small></div><nav>{panelItems.map(([key,label,Icon])=><button key={key} className={panel===key?"active":""} onClick={()=>setPanel(key)}><Icon size={16}/>{label}</button>)}</nav><div className="owned-territories"><span>SEUS TERRITÓRIOS</span>{own.map(n=><button key={n.countryId} className={selected===n.countryId?"active":""} onClick={()=>setSelected(n.countryId)}>{countries.find(c=>c.id===n.countryId)?.name??n.countryId}<small>{Object.values(n.units).reduce((a,b)=>a+b,0)} unidades</small></button>)}</div><button className="back-link rail-exit" onClick={onLeave}><LogOut size={14}/> ABANDONAR SALA</button></aside>
 <section className={`map-column ${mobileTab==="info"?"mobile-info":""}`}><div className="resource-bar">{(["money","oil","food","energy","ore"] as const).map((key,i)=><div className="resource-chip" key={key}><span className={`resource-symbol r${i}`}>{["$","◈","⌁","ϟ","◆"][i]}</span><span>{resourceNames[key].toUpperCase()}<b>{Math.floor(myNation?.resources[key]??0).toLocaleString("pt-BR")}</b></span></div>)}<div className="resource-chip population-chip"><Users size={15}/><span>POPULAÇÃO<b>{myNation?.population.toFixed(1)??"0"}M</b></span></div><div className="map-mode-select">{(["political","economic","military","diplomacy"] as const).map((value,i)=><button key={value} className={mode===value?"active":""} onClick={()=>setMode(value)}>{["POLÍTICO","ECONÔMICO","MILITAR","DIPLOMACIA"][i]}</button>)}</div></div><div className="map-game-wrap"><WorldMap countries={countries} game={game} viewerId={profile.id} selected={selected} onSelect={setSelected} mode={mode}/><div className="map-top-overlay"><span><i/> MAPA MUNDIAL · FRONTEIRAS REAIS</span><span>CICLO {game.turn} <b>·</b> {active?"SUA VEZ":"VEZ DE "+(game.players.find(p=>p.id===game.activePlayerId)?.name??"IA").toUpperCase()}</span></div><div className="turn-control"><div className="turn-countdown"><Clock3 size={15}/><b>{Math.floor(remaining/60).toString().padStart(2,"0")}:{(remaining%60).toString().padStart(2,"0")}</b><span>ATÉ O FIM DO CICLO</span></div><button className="primary-button" disabled={!active||busy||game.status!=="active"} onClick={()=>issue({type:"end_turn"})}>ENCERRAR JOGADA <ArrowRight size={15}/></button></div><button className="mobile-info-toggle" onClick={()=>setMobileTab(mobileTab==="map"?"info":"map")}>{mobileTab==="map"?"PAINEL DA NAÇÃO":"VOLTAR AO MAPA"}<ChevronRight size={14}/></button></div><div className={`game-bottom ${chatExpanded?"chat-expanded":""}`}><div className="event-feed"><div className="feed-heading"><ScrollText size={14}/> REGISTRO DE OPERAÇÕES <span>ÚLTIMOS EVENTOS</span></div><div className="feed-items">{game.events.slice(0,5).map(event=><div className={`feed-item event-${event.type}`} key={event.id}><i/><span>{event.text}</span><small>C{event.turn}</small></div>)}</div></div><div className="game-chat"><button className="feed-heading chat-title" onClick={()=>setChatExpanded(!chatExpanded)}><Radio size={14}/> CHAT DE SALA <span>{messages.length} MENSAGENS</span><ChevronDown size={14}/></button>{chatExpanded&&<><div className="chat-messages">{messages.slice(-30).map(m=><p key={m.id}><b>{m.playerName}</b><span>{m.text}</span></p>)}</div><form className="chat-compose" onSubmit={onChat}><input value={chatText} onChange={e=>setChatText(e.target.value)} maxLength={300} placeholder="Mensagem para a sala…"/><button aria-label="Enviar mensagem"><Send size={15}/></button></form></>}</div></div></section>
 <aside className="inspector"><div className="inspector-top"><div><div className="eyebrow"><span className="eyebrow-line"/> {panel==="overview"?"INTELIGÊNCIA TERRITORIAL":panelItems.find(([k])=>k===panel)?.[1].toUpperCase()}</div><h2>{panel==="overview"?selectedInfo?.name??"Selecione uma nação":panelItems.find(([k])=>k===panel)?.[1]}</h2></div><button className="icon-button info-close" onClick={()=>setPanel("overview")} aria-label="Fechar painel"><X size={16}/></button></div>
   {panel==="overview"&&<OverviewPanel game={game} country={selectedInfo??null} nation={selectedNation} owner={selectedPlayer?.name??(selectedNation?.ownerId?.startsWith("neutral-")?"Governo local":null)} own={ownSelected} viewerId={profile.id} rules={rules} busy={busy} selected={selected} adjacent={adjacent} relation={relation} onAction={issue} onPanel={setPanel} onSelectCountry={setSelected}/>}
   {panel==="economy"&&<EconomyPanel nation={myNation??null} countryName={countries.find(c=>c.id===myNation?.countryId)?.name??""} rules={rules} active={active} busy={busy} selected={myNation?.countryId??null} issue={issue}/>}
   {panel==="military"&&<MilitaryPanel game={game} nation={myNation??null} selected={myNation?.countryId??null} countries={countries} active={active} busy={busy} rules={rules} issue={issue}/>}
   {panel==="technology"&&<TechnologyPanel nation={myNation??null} selected={myNation?.countryId??null} active={active} busy={busy} rules={rules} issue={issue}/>}
   {panel==="diplomacy"&&<DiplomacyPanel game={game} profile={profile} nation={myNation??null} players={game.players.filter(p=>!p.id.startsWith("ai-")&&p.id!==profile.id)} countries={countries} targetId={targetId} setTargetId={setTargetId} relation={relation} active={active} busy={busy} give={tradeGive} setGive={setTradeGive} receive={tradeReceive} setReceive={setTradeReceive} tradeAmount={tradeAmount} setTradeAmount={setTradeAmount} issue={issue}/>}
   {panel==="espionage"&&<EspionagePanel game={game} nation={myNation??null} countries={countries} selected={targetId} setSelected={setTargetId} active={active} busy={busy} issue={issue}/>}
   {game.status==="finished"&&<div className="victory-card"><Trophy/><b>{game.winnerId===profile.id?"VITÓRIA ESTRATÉGICA":"CAMPANHA ENCERRADA"}</b><span>{game.winnerName?`${game.winnerName} conquistou a vitória.`:"Não houve vencedor nesta campanha."}</span><button onClick={onLeave}>VOLTAR AO MENU</button></div>}
 </aside></div>;
}

function OverviewPanel({game,country,nation,owner,own,viewerId,rules,busy,selected,adjacent,relation,onAction,onPanel,onSelectCountry}:{game:GameState;country:CountryInfo|null;nation:GameState["nations"][string]|null;owner:string|null;own:boolean;viewerId:string;rules:Rules|null;busy:boolean;selected:string|null;adjacent:CountryInfo[];relation:(a:string,b:string)=>string;onAction:(a:Record<string,unknown>)=>void;onPanel:(p:Panel)=>void;onSelectCountry:(id:string)=>void}){
 if(!country)return <div className="inspector-empty"><Globe2/><b>Selecione uma nação</b><span>Clique em qualquer país do mapa para inspecionar seus dados.</span></div>;
 const units=nation?Object.entries(nation.units).filter(([,count])=>count>0):[];const forceValue=(n:GameState["nations"][string])=>Object.entries(n.units).reduce((sum,[unit,count])=>sum+count*(rules?.units[unit as GameUnit]?.attack??1),0)*(1+n.technology*0.025)*(0.6+n.morale/250)*(n.resources.oil>0&&n.resources.food>0?1:0.68);const strongestAdjacent=Object.values(game.nations).filter(n=>n.ownerId===viewerId&&country.neighbors.includes(n.countryId)).sort((a,b)=>forceValue(b)-forceValue(a))[0];const myCountry=game.nations[country.id]?.ownerId===viewerId?country.id:strongestAdjacent?.countryId;
 const canWar=!own&&Boolean(myCountry)&&relation(myCountry!,country.id)!=="war";const atWar=myCountry?relation(myCountry,country.id)==="war":false;const neighbor=Boolean(myCountry&&country.neighbors.includes(myCountry));
 return <div className="inspect-scroll"><div className="country-flag">{country.code.slice(0,2)}<span>{country.continent.toUpperCase()} · {country.code}</span></div>{owner&&<div className={`owner-banner ${own?"own-banner":""}`}><span/> {own?"SOB SEU CONTROLE":`GOVERNO · ${owner.toUpperCase()}`}</div>}<div className="country-stats"><div><span>POPULAÇÃO</span><b>{(nation?.population||country.population).toFixed(1)}M</b></div><div><span>PIB / CICLO</span><b>{(nation?.gdp||country.gdp).toLocaleString("pt-BR")}</b></div><div><span>ESTABILIDADE</span><b>{nation?`${nation.stability}%`:`${country.stability}%`}</b></div><div><span>TECNOLOGIA</span><b>{nation?.technology??country.technology} <small>NV.</small></b></div><div><span>FORÇA MILITAR</span><b>{nation?Object.values(nation.units).reduce((a,b)=>a+b,0).toLocaleString():country.military}</b></div><div><span>CAPITAL</span><b className="capital-name">{country.capital}</b></div></div>
 {nation&&<><div className="inspector-section"><div className="panel-heading"><span>RESERVAS CONHECIDAS</span><Eye size={14}/></div><div className="intel-resources">{Object.entries(nation.resources).map(([key,value])=><span key={key}>{resourceNames[key]}<b>{Math.floor(value).toLocaleString("pt-BR")}</b></span>)}</div></div><div className="inspector-section"><div className="panel-heading"><span>FORÇAS MOBILIZADAS</span><span>{units.reduce((sum,[,v])=>sum+v,0)} UNIDADES</span></div>{units.length?units.slice(0,8).map(([key,count])=><div className="unit-row compact" key={key}><span>{rules?.units[key as GameUnit]?.name??key}</span><b>{count}</b></div>):<span className="muted-copy">Nenhuma força identificada.</span>}</div></>}
 {own&&<div className="quick-actions"><button onClick={()=>onPanel("economy")}><Coins size={14}/> ECONOMIA</button><button onClick={()=>onPanel("military")}><Swords size={14}/> MOBILIZAR</button></div>}
 {!own&&selected&&<div className="country-orders"><div className="panel-heading"><span>ORDENS DIPLOMÁTICAS</span><EyeOff size={14}/></div>{canWar&&<button className="danger-action" disabled={busy||!neighbor} onClick={()=>onAction({type:"declare_war",targetCountry:country.id,countryId:myCountry})}><Swords size={14}/> DECLARAR GUERRA</button>}{atWar&&neighbor&&<button className="danger-action" disabled={busy} onClick={()=>onAction({type:"attack",fromCountry:myCountry,targetCountry:country.id})}><Crosshair size={14}/> INVADIR FRONTEIRA</button>}<small>{neighbor?"País vizinho · invasão terrestre disponível":"Sem fronteira terrestre direta"}</small></div>}
 <div className="country-neighbors"><span>FRONTEIRAS TERRESTRES</span><div>{adjacent.map(c=><button key={c.id} onClick={()=>onSelectCountry(c.id)} title={c.name}>{c.code}</button>)}{!adjacent.length&&<i>Ilha ou território sem vizinhos visíveis</i>}</div></div></div>;
}

function EconomyPanel({nation,countryName,rules,active,busy,selected,issue}:{nation:GameState["nations"][string]|null;countryName:string;rules:Rules|null;active:boolean;busy:boolean;selected:string|null;issue:(a:Record<string,unknown>)=>void}){if(!nation||!selected)return <PanelEmpty text="Selecione um de seus territórios para administrar a economia."/>;return <div className="inspect-scroll"><p className="panel-lede">Produção, consumo e infraestrutura em {countryName}.</p><div className="country-stats compact-stats">{Object.entries(nation.resources).map(([key,value])=><div key={key}><span>{resourceNames[key]?.toUpperCase()}</span><b>{Math.floor(value).toLocaleString("pt-BR")}</b></div>)}<div><span>PIB</span><b>{nation.gdp.toLocaleString("pt-BR")}</b></div></div><div className="panel-heading section-margin"><span>INFRAESTRUTURA</span><span>EM CONSTRUÇÃO {nation.construction.length}/3</span></div>{(rules?buildingKeys:[]).map(key=>{const spec=rules!.buildings[key];const Icon=iconByBuilding[key];return <div className="build-order" key={key}><Icon size={17}/><div><b>{spec.name}</b><small>{spec.effect}</small><small>Custo {spec.cost.money} créditos · {spec.cost.ore} minério · {spec.turns} ciclos</small></div><button disabled={!active||busy||nation.construction.length>=3||nation.resources.money<spec.cost.money||nation.resources.ore<spec.cost.ore} onClick={()=>issue({type:"build",building:key,countryId:selected})}><Plus size={14}/></button></div>})}{nation.construction.map((c,i)=><div className="project-progress" key={i}><Clock3 size={13}/>{rules?.buildings[c.type].name}<b>{c.turnsLeft} ciclos</b></div>)}</div>}

function MilitaryPanel({game,nation,selected,countries,active,busy,rules,issue}:{game:GameState;nation:GameState["nations"][string]|null;selected:string|null;countries:CountryInfo[];active:boolean;busy:boolean;rules:Rules|null;issue:(a:Record<string,unknown>)=>void}){const [amount,setAmount]=useState(1);const [target,setTarget]=useState("");if(!nation||!selected)return <PanelEmpty text="Selecione um de seus territórios para comandar o exército."/>;return <div className="inspect-scroll"><p className="panel-lede">Forças terrestres e aéreas, logística e mobilização autorizadas pelo servidor.</p><div className="army-summary"><Swords/><div><b>{Object.values(nation.units).reduce((a,b)=>a+b,0).toLocaleString()}</b><span>UNIDADES · MORAL {nation.morale}%</span></div><select value={amount} onChange={e=>setAmount(Number(e.target.value))}>{[1,2,3,5,10].map(n=><option key={n}>{n}</option>)}</select></div><div className="panel-heading section-margin"><span>ORDEM DE PRODUÇÃO</span></div>{rules&&unitKeys.map(key=>{const spec=rules.units[key];const Icon=unitIcons[key];const locked=Boolean(spec.tech&&!nation.technologies.includes(spec.tech))||(["ships","submarines","carriers"].includes(key)&&!nation.buildings.port);return <div className={`build-order ${locked?"locked-order":""}`} key={key}><Icon size={16}/><div><b>{spec.name} <i>×{nation.units[key]}</i></b><small>ATK {spec.attack} · DEF {spec.defense} · VEL {spec.speed}</small><small>Custo {spec.cost.money} CR · {spec.cost.ore} MIN · {spec.cost.oil} OIL · UPKEEP {spec.upkeep}</small></div><button disabled={!active||busy||locked||nation.resources.money<spec.cost.money*amount||nation.resources.ore<spec.cost.ore*amount||nation.resources.oil<spec.cost.oil*amount} title={locked?`Requisito: ${spec.tech??"porto"}`:"Recrutar unidades"} onClick={()=>issue({type:"recruit",unit:key,amount,countryId:selected})}><Plus size={14}/></button></div>})}<div className="panel-heading section-margin"><span>MOVIMENTAÇÃO DE TROPAS</span></div><p className="small-copy">Selecione um território aliado adjacente no mapa antes de transferir tropas.</p><label className="select-country">Unidade<select value={target} onChange={e=>setTarget(e.target.value)}><option value="">Escolha uma unidade…</option>{unitKeys.filter(k=>nation.units[k]>0).map(k=><option key={k} value={k}>{rules?.units[k].name} · {nation.units[k]}</option>)}</select></label>{target&&countries.filter(c=>c.neighbors.includes(selected)&&game.nations[c.id]?.ownerId===nation.ownerId).map(c=><button className="secondary-button move-button" key={c.id} disabled={!active||busy} onClick={()=>issue({type:"move",fromCountry:selected,targetCountry:c.id,unit:target,amount:Math.min(amount,nation.units[target as GameUnit])})}><ArrowRight size={14}/> ENVIAR PARA {c.name.toUpperCase()}</button>)}</div>}

function TechnologyPanel({nation,selected,active,busy,rules,issue}:{nation:GameState["nations"][string]|null;selected:string|null;active:boolean;busy:boolean;rules:Rules|null;issue:(a:Record<string,unknown>)=>void}){if(!nation||!selected)return <PanelEmpty text="Escolha um de seus territórios para conduzir pesquisas."/>;return <div className="inspect-scroll"><p className="panel-lede">Pesquisa militar, economia, indústria, energia e inteligência. Benefícios aplicam-se no ciclo seguinte.</p><div className="tech-summary"><FlaskConical/><span>NÍVEL TECNOLÓGICO<b>{nation.technology}</b></span><span>PESQUISADAS<b>{nation.technologies.length}</b></span></div>{nation.research&&<div className="research-active"><Activity size={15}/><span>{rules?.technologies[nation.research.id]?.name??nation.research.id}</span><b>{nation.research.turnsLeft} ciclos</b></div>}{rules&&Object.entries(rules.technologies).map(([id,tech])=>{const done=nation.technologies.includes(id);const blocked=tech.requires.some(req=>!nation.technologies.includes(req));return <div className={`tech-card ${done?"tech-done":""}`} key={id}><div className="tech-card-head"><span>{tech.category.toUpperCase()}</span>{done?<Check size={14}/>:<span>{tech.turns} CICLOS</span>}</div><b>{tech.name}</b><p>{tech.effect}</p><small>{blocked?`Requer: ${tech.requires.map(req=>rules.technologies[req]?.name??req).join(", ")}`:`Custo de pesquisa: ${tech.cost} créditos`}</small><button disabled={!active||busy||done||blocked||Boolean(nation.research)||nation.resources.money<tech.cost} onClick={()=>issue({type:"research",technology:id,countryId:selected})}>{done?"CONCLUÍDA":nation.research?.id===id?"EM PESQUISA":"PESQUISAR"}<ArrowRight size={13}/></button></div>})}</div>}

function DiplomacyPanel({game,profile,nation,players,countries,targetId,setTargetId,relation,active,busy,give,setGive,receive,setReceive,tradeAmount,setTradeAmount,issue}:{game:GameState;profile:Profile;nation:GameState["nations"][string]|null;players:RoomPlayer[];countries:CountryInfo[];targetId:string;setTargetId:(v:string)=>void;relation:(a:string,b:string)=>string;active:boolean;busy:boolean;give:string;setGive:(v:string)=>void;receive:string;setReceive:(v:string)=>void;tradeAmount:number;setTradeAmount:(v:number)=>void;issue:(a:Record<string,unknown>)=>void}){const selectedPlayer=players.find(p=>p.id===targetId);const selectedCountry=countries.find(c=>c.id===selectedPlayer?.countryId);const myNation=nation;const status=selectedCountry&&myNation?relation(myNation.countryId,selectedCountry.id):"neutral";const incoming=game.offers.map((offer,index)=>({offer,index})).filter(item=>item.offer.to===profile.id);return <div className="inspect-scroll"><p className="panel-lede">Propostas são validadas no servidor e aceitas pelo destinatário.</p>{incoming.length>0&&<div className="incoming-offers"><b>PROPOSTAS RECEBIDAS</b>{incoming.map(({offer,index})=><div key={`${offer.from}-${index}`}><span>{offer.type==="alliance"?"Aliança militar":"Tratado de paz"}</span><button onClick={()=>issue({type:"respond_offer",offerIndex:index,accept:true})}><Check size={14}/></button><button onClick={()=>issue({type:"respond_offer",offerIndex:index,accept:false})}><X size={14}/></button></div>)}</div>}<label className="select-country">Comandante<select value={targetId} onChange={e=>setTargetId(e.target.value)}><option value="">Selecione um aliado…</option>{players.map(p=><option key={p.id} value={p.id}>{p.name} · {countries.find(c=>c.id===p.countryId)?.name??"Sem país"}</option>)}</select></label>{selectedPlayer&&selectedCountry&&myNation&&<><div className="relation-card"><Handshake/><span>RELAÇÃO DIPLOMÁTICA<b>{status.toUpperCase()}</b></span></div><div className="diplomacy-buttons"><button disabled={!active||busy||status==="alliance"} onClick={()=>issue({type:"offer",targetPlayerId:selectedPlayer.id,treaty:"alliance"})}>PROPOR ALIANÇA</button><button disabled={!active||busy||status!=="war"} onClick={()=>issue({type:"offer",targetPlayerId:selectedPlayer.id,treaty:"peace"})}>PROPOR PAZ</button></div>{status==="alliance"&&<div className="trade-card"><b>TROCA DE RECURSOS</b><label>Oferecer<select value={give} onChange={e=>setGive(e.target.value)}>{Object.entries(resourceNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Quantidade<input type="number" min="1" max="1000" value={tradeAmount} onChange={e=>setTradeAmount(Number(e.target.value))}/></label><label>Receber<select value={receive} onChange={e=>setReceive(e.target.value)}>{Object.entries(resourceNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><button disabled={!active||busy} onClick={()=>issue({type:"trade",targetPlayerId:selectedPlayer.id,give,giveAmount:tradeAmount,receive,receiveAmount:tradeAmount})}>EXECUTAR TROCA VALIDADA</button></div>}</>}</div>}

function EspionagePanel({game,nation,countries,selected,setSelected,active,busy,issue}:{game:GameState;nation:GameState["nations"][string]|null;countries:CountryInfo[];selected:string;setSelected:(v:string)=>void;active:boolean;busy:boolean;issue:(a:Record<string,unknown>)=>void}){if(!nation)return <PanelEmpty text="Controle um território para administrar sua rede de inteligência."/>;const hasTech=nation.technologies.includes("unmanned_systems");const targets=Object.values(game.nations).filter(n=>n.ownerId&&n.ownerId!==nation.ownerId);return <div className="inspect-scroll"><p className="panel-lede">Fog of War oculta forças e reservas fora dos países vizinhos.</p><div className="intel-brief"><Eye/><div><b>{targets.length} nações identificadas</b><span>{hasTech?"Sabotagem operacional · custo 180 créditos":"Pesquise Sistemas não tripulados para habilitar sabotagem"}</span></div></div><label className="select-country">Alvo<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Selecione uma nação adversária…</option>{targets.map(n=><option key={n.countryId} value={n.countryId}>{countries.find(c=>c.id===n.countryId)?.name??n.ownerName}</option>)}</select></label><button className="danger-action" disabled={!hasTech||!selected||!active||busy} onClick={()=>issue({type:"sabotage",targetCountry:selected})}><EyeOff size={14}/> ORDENAR SABOTAGEM</button><div className="small-copy">A tentativa é decidida pelo servidor. Contraespionagem inimiga pode detectar e bloquear a operação. Nenhuma origem é anunciada no registro público.</div></div>}

function PanelEmpty({text}:{text:string}){return <div className="inspector-empty"><Target/><span>{text}</span></div>}
function ProfilePage({profile,onSave}:{profile:Profile;onSave:(name:string)=>Promise<void>}){const [name,setName]=useState(profile.name);return <div className="subpage"><div className="eyebrow"><span className="eyebrow-line"/> REGISTRO DE COMANDANTE</div><h1 className="subpage-title">Seu <em>perfil.</em></h1><div className="profile-card"><span className="profile-avatar">{profile.avatar}</span><div><b>{profile.name}</b><small>MEMBRO DESDE {new Date(profile.createdAt).toLocaleDateString("pt-BR")}</small></div></div><div className="profile-stats">{[["VITÓRIAS",profile.wins],["DERROTAS",profile.losses],["PARTIDAS",profile.matches],["PONTUAÇÃO",profile.score]].map(([label,value])=><div key={label}><span>{label}</span><b>{Number(value).toLocaleString("pt-BR")}</b></div>)}</div><form className="form-card profile-form" onSubmit={e=>{e.preventDefault();void onSave(name);}}><label>Nome de comandante<input value={name} onChange={e=>setName(e.target.value)} minLength={2} maxLength={24}/></label><p className="form-note">Países comandados: {profile.countriesUsed.length?profile.countriesUsed.length:"nenhum"}. O histórico de partidas e a pontuação são persistidos no servidor local.</p><button className="primary-button">SALVAR PERFIL <Check size={15}/></button></form></div>}
function RankingPage({api,flash}:{api:<T,>(path:string,init?:RequestInit)=>Promise<T>;flash:(m:string)=>void}){const [ranking,setRanking]=useState<Profile[]>([]);useEffect(()=>{let live=true;void api<{ranking:Profile[]}>("/api/ranking").then(x=>{if(live)setRanking(x.ranking);}).catch(e=>flash(e.message));return()=>{live=false;};},[api,flash]);return <div className="subpage"><div className="eyebrow"><span className="eyebrow-line"/> RANKING PERSISTENTE</div><h1 className="subpage-title">Comandantes <em>globais.</em></h1><div className="ranking-table"><div className="ranking-head"><span>#</span><span>COMANDANTE</span><span>PTS</span><span>VIT</span><span>DER</span><span>PARTIDAS</span></div>{ranking.length?ranking.map((p,i)=><div className="ranking-row" key={p.id}><span>{String(i+1).padStart(2,"0")}</span><b><i>{p.avatar}</i>{p.name}</b><span>{p.score}</span><span>{p.wins}</span><span>{p.losses}</span><span>{p.matches}</span></div>):<div className="empty-state"><Trophy/><b>A classificação está aberta.</b><span>Resultados são registrados ao concluir uma partida.</span></div>}</div></div>}
function SettingsPage({profile,sound,setSound,online,onSave}:{profile:Profile|null;sound:boolean;setSound:(v:boolean)=>void;online:boolean;onSave:(name:string)=>Promise<void>}){const [name,setName]=useState(profile?.name??"");return <div className="subpage"><div className="eyebrow"><span className="eyebrow-line"/> PREFERÊNCIAS DO SISTEMA</div><h1 className="subpage-title">Configurações <em>de comando.</em></h1><div className="form-card settings-card"><label>Nome de comandante<input value={name} onChange={e=>setName(e.target.value)} minLength={2} maxLength={24}/></label><button className="secondary-button" onClick={()=>void onSave(name)}>SALVAR PERFIL</button><div className="toggle-row"><span><b>Efeitos da interface</b><small>Ativa notificações e feedback sonoro leve.</small></span><button role="switch" aria-checked={sound} className={`switch ${sound?"active":""}`} onClick={()=>{const next=!sound;setSound(next);localStorage.setItem("wf-sound",next?"on":"off");}}>{sound?<Check size={13}/>:<X size={13}/>}</button></div><div className="setting-static"><span><b>Qualidade gráfica</b><small>Auto · mapa vetorial renderizado localmente</small></span><span>ALTA</span></div><div className="setting-static"><span><b>Idioma</b><small>Português (Brasil) · rótulos de jogo localizados</small></span><span>PT-BR</span></div><button className="secondary-button" onClick={()=>{if(document.fullscreenElement)void document.exitFullscreen();else void document.documentElement.requestFullscreen();}}>ALTERNAR TELA CHEIA <ArrowRight size={14}/></button></div><div className="server-settings"><span className={`status-dot ${online?"online":"offline"}`}/> API e Socket.IO {online?"conectados":"reconectando"} · armazenamento persistente do servidor.</div></div>}
